INSERT INTO `wp_khm_email_queue` VALUES (5,6,'welcome','toggle-evidence+1772477056@example.com','Welcome to your membership','<h2>Welcome to Touchpoint-Template, toggle-evidence1772477056@example.com</h2>\n\n<p>Your <strong>E2E Pro</strong> membership is now active.</p>\n\n<h3>What happened</h3>\n<ul>\n  <li><strong>Start date:</strong> 2026-03-02</li>\n  <li><strong>Trial end:</strong> </li>\n  <li><strong>Reference:</strong> cs_toggle_on_1772477056</li>\n</ul>\n\n<h3>Attribution details</h3>\n<ul>\n  <li><strong>Schedule:</strong> 888</li>\n  <li><strong>Sponsor:</strong> E2E Sponsor</li>\n  <li><strong>Campaign source:</strong> toggle-test</li>\n</ul>\n\n<h3>Next steps</h3>\n<p>\n  Access your membership dashboard at <a href=\"http://touchpoint-template-remote.local/account/\">http://touchpoint-template-remote.local/account/</a>.\n</p>\n<p>\n  Need help? Contact us at dev-email@wpengine.local and include reference <strong>cs_toggle_on_1772477056</strong>.\n</p>\n\n<p>\n  Manage your email preferences: <a href=\"http://touchpoint-template-remote.local/account/\">http://touchpoint-template-remote.local/account/</a>\n</p>\n','[\"Content-Type: text\\/html; charset=UTF-8\"]','[]','{\"user_name\":\"toggle-evidence1772477056@example.com\",\"membership_tier\":\"E2E Pro\",\"start_date\":\"2026-03-02\",\"trial_end\":\"\",\"amount\":\"\",\"currency\":\"GBP\",\"schedule_id\":\"888\",\"sponsor_name\":\"E2E Sponsor\",\"utm_source\":\"toggle-test\",\"reference\":\"cs_toggle_on_1772477056\",\"support_contact\":\"dev-email@wpengine.local\",\"account_url\":\"http:\\/\\/touchpoint-template-remote.local\\/account\\/\",\"preferences_url\":\"http:\\/\\/touchpoint-template-remote.local\\/account\\/\",\"siteurl\":\"http:\\/\\/touchpoint-template-remote.local\",\"sitename\":\"Touchpoint-Template\"}',5,0,3,'failed','Failed to send email','2026-03-02 18:44:16','2026-03-02 18:44:16',NULL,'2026-03-02 18:44:16',NULL),(6,7,'payment_confirmation','toggle-evidence+1772477056@example.com','Your membership payment confirmation','<h2>Payment confirmation for E2E Pro</h2>\n\n<p>Hi toggle-evidence1772477056@example.com,</p>\n\n<p>\n  We have received your payment of <strong>0 GBP</strong>.\n</p>\n\n<h3>Payment details</h3>\n<ul>\n  <li><strong>Reference:</strong> cs_toggle_on_1772477056</li>\n  <li><strong>Schedule:</strong> 888</li>\n  <li><strong>Sponsor:</strong> E2E Sponsor</li>\n  <li><strong>Campaign source:</strong> toggle-test</li>\n</ul>\n\n<h3>Next steps</h3>\n<p>\n  Visit your account dashboard: <a href=\"http://touchpoint-template-remote.local/account/\">http://touchpoint-template-remote.local/account/</a>\n</p>\n<p>\n  If something looks wrong, contact dev-email@wpengine.local and include reference <strong>cs_toggle_on_1772477056</strong>.\n</p>\n\n<p>\n  Manage your email preferences: <a href=\"http://touchpoint-template-remote.local/account/\">http://touchpoint-template-remote.local/account/</a>\n</p>\n','[\"Content-Type: text\\/html; charset=UTF-8\"]','[]','{\"user_name\":\"toggle-evidence1772477056@example.com\",\"membership_tier\":\"E2E Pro\",\"start_date\":\"2026-03-02\",\"trial_end\":\"\",\"amount\":0,\"currency\":\"GBP\",\"schedule_id\":\"888\",\"sponsor_name\":\"E2E Sponsor\",\"utm_source\":\"toggle-test\",\"reference\":\"cs_toggle_on_1772477056\",\"support_contact\":\"dev-email@wpengine.local\",\"account_url\":\"http:\\/\\/touchpoint-template-remote.local\\/account\\/\",\"preferences_url\":\"http:\\/\\/touchpoint-template-remote.local\\/account\\/\",\"siteurl\":\"http:\\/\\/touchpoint-template-remote.local\",\"sitename\":\"Touchpoint-Template\"}',5,0,3,'failed','Failed to send email','2026-03-02 18:44:16','2026-03-02 18:44:16',NULL,'2026-03-02 18:44:16',NULL),(7,10,'welcome','dev-email@wpengine.local','','<p>Queue body</p>','[\"Content-Type: text\\/html; charset=UTF-8\"]','[]','{\"reference\":\"session:postmerge_email_dup_001\"}',5,0,3,'sent',NULL,'2026-03-07 23:56:40','2026-03-07 23:56:40','2026-03-07 23:56:40','2026-03-07 23:56:40','wel